#ifndef DMR_DEMODULATOR_H
#define DMR_DEMODULATOR_H

#ifndef __cplusplus
#error This header is C++ only!
#endif

#include <cstddef>
#include <cstdint>
#include <memory>
#include "core/audio_path.h"
#include "core/audio_stream.h"
#include "protocols/DMR/Constants.hpp"
#include "protocols/DMR/Voice.hpp"

namespace DMR
{

/**
 * Event generated by the DMR receiver.
 */
struct Event {
    enum Type : uint8_t {
        BURST, ///< Burst received, see sync and burst
        LOST   ///< Synchronisation lost, no sync for too long
    } type;

    /// BURST only: sync found in the burst. Bursts without sync are only
    /// reported after a sync has been found, at the same position in the
    /// following TDMA frames.
    SyncType sync;

    /// BURST only: burst bits, MMDVM bit order
    uint8_t burst[BURST_BYTES];
};

/**
 * DMR direct mode 4FSK receiver, a port of MMDVM's DMR receive chain (IO.cpp
 * DC removal and root raised cosine filter, DMRDMORX.cpp synchronisation and
 * symbol decisions). It has no dependency on the audio subsystem.
 *
 * Input: baseband (FM discriminator) samples at 24 kHz, 5 per symbol. A
 * positive sample is a positive frequency deviation (see invertPhase()). The
 * symbol decision levels are taken from the received syncs, the amplitude is
 * irrelevant.
 *
 * Memory: about 3 kB, all statically sized members (the largest being the
 * 1440 samples, one TDMA frame, of the sample history).
 */
class Receiver
{
public:
    /// Input sample rate, in Hz
    static constexpr uint32_t SAMPLE_RATE = 24000;

    /// Input samples per symbol
    static constexpr size_t SAMPLES_PER_SYMBOL = SAMPLE_RATE / SYMBOL_RATE;

    /// TDMA frames without sync before the synchronisation is lost
    static constexpr size_t MAX_LOST_FRAMES = 13;

    /// Capacity of the event queue
    static constexpr size_t EVENT_QUEUE_SIZE = 4;

    /**
     * Constructor.
     */
    Receiver();

    /**
     * \brief Reset the receiver state, pending events included. The phase
     * inversion setting is kept.
     */
    void reset();

    /**
     * \brief Drop the synchronisation and look for a new transmission, with
     * any timing, e.g. after a terminator. Pending events are kept.
     */
    void unlock();

    /**
     * \brief Invert the phase of the input signal.
     *
     * @param invert: if true, the input signal phase is inverted.
     */
    void invertPhase(bool invert);

    /**
     * \brief Process a block of baseband samples.
     *
     * When more than EVENT_QUEUE_SIZE events are pending, the oldest ones are
     * dropped: call popEvent() often enough (at least once every 3840
     * samples).
     *
     * @param samples: baseband samples, 24 kHz.
     * @param count: number of samples.
     */
    void process(const int16_t *samples, size_t count);

    /**
     * \brief Get the oldest pending event.
     *
     * @param ev: event, written only if one is pending.
     * @return true if an event has been returned.
     */
    bool popEvent(Event &ev);

    /**
     * \brief Check for pending events.
     *
     * @return true if at least one event is pending.
     */
    bool hasEvents() const;

    /**
     * \brief Check if the receiver is locked on a transmission.
     *
     * @return true between the reception of a sync and the loss of the
     * synchronisation.
     */
    bool isLocked() const;

private:
    /// Samples of a TDMA frame (60 ms), length of the sample history
    static constexpr size_t FRAME_SAMPLES = FRAME_SYMBOLS * SAMPLES_PER_SYMBOL;

    /// Taps of the receive filter
    static constexpr size_t FILTER_TAPS = 41;

    /// Sync type of the current frame
    enum class Control : uint8_t { NONE, VOICE, DATA };

    /**
     * Remove the DC offset and apply the receive filter.
     *
     * @param raw: input sample.
     * @return filtered sample.
     */
    int16_t filter(int16_t raw);

    /**
     * Look for a sync ending at the current sample, keeping the best
     * correlating one and the decision levels it gives.
     *
     * @param first: true when not locked yet.
     */
    void correlateSync(bool first);

    /**
     * Correlate the samples of a sync with its pattern.
     *
     * @param last: position of the sample of the last sync symbol.
     * @param pattern: sync symbol signs, e.g. MS_DATA_SYNC_SIGNS.
     * @return correlation value.
     */
    int32_t correlate(size_t last, uint32_t pattern) const;

    /**
     * Estimate the position of the correlation peak of the last sync
     * between samples, from the correlation at the samples around it.
     *
     * @return the offset of the peak, in 1/256 of a sample, -128 to 128.
     */
    int16_t estimateTiming() const;

    /**
     * Turn samples into bits with the current decision levels.
     *
     * @param start: position of the first sample in the history.
     * @param count: number of symbols.
     * @param buffer: output bits, MMDVM order.
     * @param offset: position of the first output bit.
     * @param centre: centre level.
     * @param threshold: +1/+3 decision threshold, from the centre.
     * @param timing: offset of the symbol centres from the samples, in
     * 1/256 of a sample: the symbols are read by quadratic interpolation.
     */
    void samplesToBits(size_t start, size_t count, uint8_t *buffer,
                       size_t offset, int16_t centre, int16_t threshold,
                       int16_t timing) const;

    /**
     * Emit the burst ending at the current sample.
     */
    void endOfBurst();

    /**
     * Append an event to the queue, dropping the oldest when it is full.
     *
     * @param ev: event to be queued.
     */
    void pushEvent(const Event &ev);

    bool inverted;        ///< Input phase inversion
    bool locked;          ///< Locked on a transmission
    Control control;      ///< Sync found in the current frame
    uint8_t bitPtr;       ///< Current sampling phase, 0 to 4
    uint8_t lostCount;    ///< Frames since the last sync
    uint8_t averagePtr;   ///< Position in centre and threshold
    uint16_t dataPtr;     ///< Current position in buffer
    uint16_t syncPtr;     ///< Position of the end of the last sync
    uint16_t endPtr;      ///< One sample after the end of the burst
    bool haveEnd;         ///< endPtr is valid
    int32_t maxCorr;      ///< Best sync correlation in this frame
    uint32_t syncPattern; ///< Sign pattern of the last sync found
    int16_t timing;       ///< Symbol timing offset, 1/256 sample
    int16_t centre[4];    ///< Last centre levels
    int16_t threshold[4]; ///< Last decision thresholds
    float dcLevel;        ///< DC level estimate
    float dcPrevIn;       ///< Previous input of the DC estimator
    uint8_t filterPtr;    ///< Position in filterBuffer
    int16_t filterBuffer[FILTER_TAPS]; ///< Receive filter history

    /// Received symbol signs, one register per sampling phase, newest in
    /// the least significant position, 1 for a positive sample
    uint32_t bitBuffer[SAMPLES_PER_SYMBOL];

    /// Sample history, one TDMA frame long
    int16_t buffer[FRAME_SAMPLES];

    Event events[EVENT_QUEUE_SIZE]; ///< Event queue
    uint8_t eventHead;              ///< Oldest event in the queue
    uint8_t eventCount;             ///< Events in the queue
};

/**
 * Demodulator device for DMR: acquisition of the baseband signal from the
 * RTX and decoding through a Receiver.
 */
class Demodulator
{
public:
    /**
     * Constructor.
     */
    Demodulator();

    /**
     * Destructor.
     */
    ~Demodulator();

    /**
     * \brief Allocate the baseband buffer and the receiver, and initialise
     * the demodulator.
     */
    void init();

    /**
     * \brief Shut down the demodulator and deallocate its memory.
     */
    void terminate();

    /**
     * \brief Start the sampling of the baseband signal in a double buffer.
     */
    void startBasebandSampling();

    /**
     * \brief Stop the sampling of the baseband signal.
     */
    void stopBasebandSampling();

    /**
     * \brief Process the baseband samples acquired since the last call.
     * Blocks until a new half of the baseband buffer is available.
     *
     * @param invertPhase: invert the phase of the baseband signal.
     * @return true if events are pending.
     */
    bool update(bool invertPhase = false);

    /**
     * \brief Get the oldest pending event.
     *
     * @param ev: event, written only if one is pending.
     * @return true if an event has been returned.
     */
    bool popEvent(Event &ev);

    /**
     * \brief Drop the synchronisation and look for a new transmission.
     */
    void unlock();

private:
    /// Samples of half the baseband buffer: 20 ms
    static constexpr size_t SAMPLE_BUF_SIZE = 480;

    std::unique_ptr<int16_t[]> basebandBuffer; ///< Baseband double buffer
    std::unique_ptr<Receiver> receiver;        ///< Receiver
    streamId basebandId;                       ///< Baseband input stream
    pathId basebandPath;                       ///< Baseband input path
};

} // namespace DMR

#endif // DMR_DEMODULATOR_H
